const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Northern Lapland, Sweden. Using a point near Kiruna as a representative location.
  const geometry = ee.Geometry.Point(20.16, 67.85).buffer(50000); // 50km buffer around Kiruna

  const dateOctStart = '2016-10-01';
  const dateOctEnd = '2016-10-15'; // Narrow window around Oct 10
  const dateSepStart = '2016-09-01';
  const dateSepEnd = '2016-09-30';

  // Sentinel-2 cloud masking function
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select('B4', 'B3', 'B8', 'B2', 'B11', 'B12', 'B5', 'B6', 'B7') // Select common bands for consistency
      .copyProperties(image, ['system:time_start']);
  }

  // 2. Data Acquisition & Check
  let collectionOct = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(dateOctStart, dateOctEnd)
    .filterBounds(geometry)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 60))
    .map(maskS2clouds);

  let collectionSep = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(dateSepStart, dateSepEnd)
    .filterBounds(geometry)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 60))
    .map(maskS2clouds);

  const sizeOct = await collectionOct.size().getInfo();
  const sizeSep = await collectionSep.size().getInfo();

  if (sizeOct === 0 || sizeSep === 0) {
    console.log(`October Images: ${sizeOct}`);
    console.log(`September Images: ${sizeSep}`);
    console.log('C1');
    return;
  }

  // Create median composites
  const imageOct = collectionOct.median();
  const imageSep = collectionSep.median();

  // Calculate "yellowness" as Red/Green ratio (B4/B3)
  // Higher ratio indicates more yellow/red (less green chlorophyll)
  const yellownessOct = imageOct.select('B4').divide(imageOct.select('B3')).rename('Yellowness');
  const yellownessSep = imageSep.select('B4').divide(imageSep.select('B3')).rename('Yellowness');

  // 3. Processing & 4. Calculation
  const scale = 1000; // Use a reasonable scale to avoid memory issues

  // Calculate valid pixel count for October
  const countOct = await yellownessOct.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('Yellowness').getInfo();

  // Calculate valid pixel count for September
  const countSep = await yellownessSep.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('Yellowness').getInfo();

  if (countOct === 0 || countSep === 0) {
    console.log(`October Images: ${sizeOct} (Valid Pixels: ${countOct})`);
    console.log(`September Images: ${sizeSep} (Valid Pixels: ${countSep})`);
    console.log('C2');
    return;
  }

  // Calculate mean yellowness for October
  const meanYellownessOct = await yellownessOct.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('Yellowness').getInfo();

  // Calculate mean yellowness for September
  const meanYellownessSep = await yellownessSep.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('Yellowness').getInfo();

  // 5. Validation & Final Answer
  if (meanYellownessOct === null || meanYellownessSep === null || isNaN(meanYellownessOct) || isNaN(meanYellownessSep)) {
    console.log(`October Yellowness: ${meanYellownessOct}`);
    console.log(`September Yellowness: ${meanYellownessSep}`);
    console.log('C3');
    return;
  }

  console.log(`October Images: ${sizeOct} (Valid Pixels: ${countOct})`);
  console.log(`September Images: ${sizeSep} (Valid Pixels: ${countSep})`);
  console.log(`Mean Yellowness (Red/Green) Oct: ${meanYellownessOct.toFixed(3)}`);
  console.log(`Mean Yellowness (Red/Green) Sep: ${meanYellownessSep.toFixed(3)}`);

  if (meanYellownessOct > meanYellownessSep) {
    console.log('A'); // Yes, more yellow in October
  } else {
    console.log('B'); // No, not more yellow in October
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
